import CutawayTestSupport
import FlatBuffers
import XCTest

@testable import CutawayWire

/// Toolchain probes: the pinned flatc and FlatBuffers runtime work together. They use the
/// generated types directly; the real decoder (C-WIRE-01) goes through this project's own value
/// types.
final class ToolchainTests: XCTestCase {
    /// Hypothesis 4: code generated by the pinned flatc compiles against the pinned runtime
    /// and reads a fixture. Hypothesis 5: the generated types are internal and reachable
    /// through `@testable import`.
    func test_M0_H4_generatedCodeReadsAFixtureFrame() throws {
        let data = try Fixtures.data(scenario: "handshake", file: "02-s2c-hello.bin")
        var buffer = ByteBuffer(data: data)

        let frame: Cutaway_Wire_Frame = try getCheckedRoot(byteBuffer: &buffer, fileId: "CTWY")

        XCTAssertEqual(frame.requestId, 0)
        XCTAssertEqual(frame.bodyType, .hello)
        let hello = try XCTUnwrap(frame.body(type: Cutaway_Wire_Hello.self))
        XCTAssertEqual(hello.role, .server)
        XCTAssertEqual(hello.protocol_?.major, 1)
        XCTAssertEqual(hello.protocol_?.minor, 0)
        XCTAssertEqual(hello.app?.name, "Demo")
    }
}
